"use client";
import { ExpandableCardCarousel } from "./expandable-card-carousel";
import data from "./data.json";

export default function Page() {
  return <ExpandableCardCarousel data={data} />;
}

"use client";
import { Carousel } from "../../ui/carousel/carousel";
import { ExpandableCard, type ExpandableCardItem } from "../../ui/expandable-card/expandable-card";
import styles from "./expandable-card-carousel.module.css";

type CardData = {
  id: number;
  imageSrc: string;
  cardHeading: string;
  alt: string;
  paragraphs: string[];
};

type ExpandableCardCarouselProps = {
  data: {
    cards: CardData[];
  };
};

export function ExpandableCardCarousel({ data }: ExpandableCardCarouselProps) {
  const items: ExpandableCardItem[] = data.cards.map((card) => ({
    id: card.id,
    imageSrc: card.imageSrc,
    cardHeading: card.cardHeading,
    alt: card.alt,
    content: (
      <div className={styles.content}>
        {card.paragraphs.map((paragraph) => (
          <p key={paragraph}>{paragraph}</p>
        ))}
      </div>
    ),
  }));

  return (
    <div className={styles.wrapper}>
      <header className={styles.header}>
        <h2 className={styles.heading}>
          Our Three Core
          <br />
          Philosophies
        </h2>
        <p className={styles.description}>
          The principles that guide everything we create, from design decisions to the experiences we craft for our
          users.
        </p>
      </header>
      <Carousel.Bleed>
        <Carousel.Root align="start" gap={24} totalItems={items.length} variant="inset">
          <Carousel.Viewport>
            <Carousel.Content className={styles.content}>
              {items.map((item, index) => (
                <Carousel.Item index={index} key={item.id}>
                  <ExpandableCard item={item} />
                </Carousel.Item>
              ))}
            </Carousel.Content>
          </Carousel.Viewport>
        </Carousel.Root>
      </Carousel.Bleed>
    </div>
  );
}

.wrapper {
  width: 100%;
  max-width: 100%;
  padding: 24px 0;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 24px;
  margin-bottom: 32px;
  padding-inline: 1rem;
}

.heading {
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 500;
  color: var(--foreground);
  margin: 0;
  letter-spacing: -0.02em;
  line-height: 1.3;
}

.description {
  font-size: var(--font-size-sm);
  color: var(--muted-foreground);
  margin: 0;
  max-width: 360px;
  text-align: left;
}

@media (max-width: 768px) {
  .header {
    flex-direction: column;
    align-items: flex-start;
  }

  .heading {
    font-size: clamp(1.875rem, 5vw, 2.75rem);
  }
}

.content {
  height: 50vh;
  align-items: center;
  justify-content: center;
}

@media (min-width: 1100px) {
  .header {
    max-width: 1008px;
    margin-left: auto;
    margin-right: auto;
    padding-inline: 0;
  }

  .bleed {
    width: auto;
    margin-left: 0;
    margin-right: 0;
    left: auto;
    right: auto;
    display: flex;
    justify-content: center;
  }

  .carouselRoot {
    width: auto;
  }
}

.content p {
  margin: 0 0 1rem 0;
}

.content p:last-child {
  margin-bottom: 0;
}

{
  "cards": [
    {
      "id": 1,
      "imageSrc": "/figure-01.webp",
      "cardHeading": "Make work easier",
      "alt": "A hooded figure by a river at night, looking up at lit stone arches and a full moon",
      "paragraphs": [
        "Good software helps people finish their work. It should never get in the way.",
        "We test each component against real tasks. If a component slows people down, we change it.",
        "When we must choose between what is easy to build and what is useful, we choose useful.",
        "The tools you build shape how people work every day. We want those tools to be clear, fast, and fair to everyone."
      ]
    },
    {
      "id": 2,
      "imageSrc": "/figure-02.webp",
      "cardHeading": "Keep it simple",
      "alt": "A hooded figure sits by the water below a lit stone arcade and a full moon",
      "paragraphs": [
        "Every part of a component needs a reason to be there. If a part does not help you, we remove it.",
        "Simple components are easier to read, change, and test.",
        "We check each line, shadow, and animation against one question: does this help the person using it?",
        "Less on the screen means people can focus on the task in front of them."
      ]
    },
    {
      "id": 3,
      "imageSrc": "/figure-03.webp",
      "cardHeading": "Get the details right",
      "alt": "A hooded figure faces a domed temple across the water under a full moon",
      "paragraphs": [
        "Small details decide whether an interface feels finished. We pay close attention to them.",
        "We handle keyboard use, focus states, screen readers, and edge cases, so you do not have to.",
        "Quality is a habit, not a final step. We review and improve components after every release.",
        "You get components that work well on day one and keep working as your product grows."
      ]
    }
  ]
}
